import React, { useState, useEffect } from 'react';

function Dashboard() {
  const [orders, setOrders] = useState([]);

  useEffect(() => {
    // Python-ல் இருந்து டேட்டாவை வாங்கி Admin டேபிளில் காட்டுதல்
    fetch('http://127.0.0.1:8000/orders')
      .then(res => res.json())
      .then(data => setOrders(data))
      .catch(err => console.error("Error fetching data:", err));
  }, []);

  return (
    <div className="admin-container">
      <div className="admin-header">
        <h2>🛡️ Admin Dashboard</h2>
        <p>Manage your customer inquiries and orders here.</p>
      </div>

      <div className="table-wrapper">
        <table className="admin-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Phone</th>
              <th>Email</th>
              <th>Service</th>
              <th>Message</th>
            </tr>
          </thead>
          <tbody>
            {orders.length === 0 ? (
              <tr><td colSpan="5" className="empty-msg">No messages yet. Waiting for customers... ⏳</td></tr>
            ) : (
              orders.map((order, index) => (
                <tr key={index}>
                  <td><strong>{order.name}</strong></td>
                  <td>{order.phone}</td>
                  <td>{order.email}</td>
                  <td><span className="badge">{order.service}</span></td>
                  <td>{order.message}</td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default Dashboard;
